#include <bits/stdc++.h>
using namespace std;

struct FastScanner {
    static const int BUFSIZE = 1 << 20;
    char buf[BUFSIZE];
    int idx, size;
    FastScanner() : idx(0), size(0) {}
    inline char getChar() {
        if (idx >= size) {
            size = fread(buf, 1, BUFSIZE, stdin);
            idx = 0;
            if (size == 0) return EOF;
        }
        return buf[idx++];
    }
    template<typename T>
    bool nextInt(T &out) {
        char c; T sign = 1; T val = 0;
        c = getChar();
        if (c == EOF) return false;
        while (c != '-' && (c < '0' || c > '9')) {
            c = getChar();
            if (c == EOF) return false;
        }
        if (c == '-') { sign = -1; c = getChar(); }
        for (; c >= '0' && c <= '9'; c = getChar()) {
            val = val * 10 + (c - '0');
        }
        out = val * sign;
        return true;
    }
    int nextInt() { int x; nextInt(x); return x; }
    long long nextLong() { long long x; nextInt(x); return x; }
};

struct Solver {
    static const int MAX = 100005;
    static const long long INF = (long long)1e18 + 10;

    vector<long long> dp;
    int a;
    long long b;
    char c;
    FastScanner cin;
    string output;

    const string f0 = "What are you doing at the end of the world? Are you busy? Will you save us?";
    const string s0 = "What are you doing while sending \"";
    const string s1 = "\"? Are you busy? Will you send \"";
    const string s2 = "\"?";

    void calc() {
        int N = cin.nextInt();
        dp.resize(MAX);
        dp[0] = f0.size();
        for (int i = 1; i < MAX; i++) {
            if (dp[i - 1] > INF / 2) dp[i] = INF;
            else dp[i] = dp[i - 1] * 2 + s0.size() + s1.size() + s2.size();
        }

        for (int i = 0; i < N; i++) {
            a = cin.nextInt();
            b = cin.nextLong() - 1;
            while (a != -1) dfs();
            output.push_back(c);
        }
        printf("%s\n", output.c_str());
    }

    void dfs() {
        if (b >= dp[a]) {
            c = '.'; a = -1; return;
        }
        if (a == 0) {
            c = f0[(size_t)b]; a = -1; return;
        }
        if (b < (long long)s0.size()) {
            c = s0[(size_t)b]; a = -1; return;
        }
        b -= s0.size();
        if (b < dp[a - 1]) {
            a--; return;
        }
        b -= dp[a - 1];
        if (b < (long long)s1.size()) {
            c = s1[(size_t)b]; a = -1; return;
        }
        b -= s1.size();
        if (b < dp[a - 1]) {
            a--; return;
        }
        b -= dp[a - 1];
        c = s2[(size_t)b];
        a = -1;
    }
};

int main() {
    Solver solver;
    solver.calc();
    return 0;
}

