#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int MAX_N = 100005;
const int64 INF = (int64)1e18 + 10;

int64 dp[MAX_N];

const string f0 = "What are you doing at the end of the world? Are you busy? Will you save us?";
const string s0 = "What are you doing while sending \"";
const string s1 = "\"? Are you busy? Will you send \"";
const string s2 = "\"?";

struct FastScanner {
    static const int BUFSIZE = 1 << 20;
    int idx, size;
    char buf[BUFSIZE];
    FastScanner() : idx(0), size(0) {}
    inline char getChar() {
        if (idx >= size) {
            size = fread(buf, 1, BUFSIZE, stdin);
            idx = 0;
            if (size == 0) return EOF;
        }
        return buf[idx++];
    }
    template<typename T>
    bool nextInt(T &out) {
        char c; T sign = 1; T val = 0;
        c = getChar();
        if (c == EOF) return false;
        while (c != '-' && (c < '0' || c > '9')) {
            c = getChar();
            if (c == EOF) return false;
        }
        if (c == '-') { sign = -1; c = getChar(); }
        for (; c >= '0' && c <= '9'; c = getChar()) val = val * 10 + (c - '0');
        out = val * sign;
        return true;
    }
} scanner;

char solve_query(int n, int64 k) {
    while (true) {
        if (k >= dp[n]) return '.';
        if (n == 0) return f0[k];

        if (k < (int64)s0.size()) return s0[k];
        k -= s0.size();

        if (k < dp[n - 1]) { n--; continue; }
        k -= dp[n - 1];

        if (k < (int64)s1.size()) return s1[k];
        k -= s1.size();

        if (k < dp[n - 1]) { n--; continue; }
        k -= dp[n - 1];

        return s2[k];
